// Object-preference registry — entry shape (sketch, not yet built)
// `name` IS the stored glyph or shape id — no aliasing, no render pointer.
// One string names the object in the registry, the picker, the agent's
// vocabulary, and the lints.
type ObjectPreference = {
  name: string; // "memory", "agent", "decision", …
  meaning: string; // one line: what this object represents
  scenarios: string[]; // "use when …" — the boards' shared language
  color: CanvasColor; // default swatch — used almost always; per-placement override allowed
};

// Example shipped defaults
const DEFAULTS: ObjectPreference[] = [
  {
    name: "memory",
    meaning: "A store an agent reads from or writes to across turns",
    scenarios: [
      "long/short-term memory, knowledge bases, vector stores",
      "the target of state-read / state-write edges",
    ],
    color: "blue",
  },
  {
    name: "agent",
    meaning: "An autonomous agent — plans and acts on its own",
    scenarios: ["main agents, sub-agents, workers in a pool"],
    color: "teal",
  },
];
